def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    total_agents = 1 + len(alive)
    likely_units = int(supply // WATER_REQ)
    scarcity = total_agents - likely_units

    prev_bids = []
    desperate_opp = False
    rich_opp = False
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_opp = True
        if opp.get('budget', 0) > budget * 1.2:
            rich_opp = True

    if hp <= 2 or no_water >= 2:
        bid = DAILY_SALARY * 0.96
    elif likely_units >= total_agents:
        bid = DAILY_SALARY * 0.18
    elif scarcity <= 1:
        bid = DAILY_SALARY * 0.42
    elif scarcity == 2:
        bid = DAILY_SALARY * 0.58
    else:
        bid = DAILY_SALARY * 0.74

    if prev_bids:
        top_prev = max(prev_bids)
        if top_prev >= DAILY_SALARY * 0.9:
            if hp > 3 and no_water == 0:
                bid = min(bid, DAILY_SALARY * 0.35)
            else:
                bid = max(bid, DAILY_SALARY * 0.9)
        elif top_prev >= DAILY_SALARY * 0.55:
            bid = max(bid, min(DAILY_SALARY * 0.78, top_prev + 1.0))
        else:
            bid = max(bid, top_prev + 0.5)

    if desperate_opp and hp > 3 and no_water == 0:
        bid = min(bid, DAILY_SALARY * 0.52)
    if rich_opp and scarcity >= 2 and (hp <= 3 or no_water >= 1):
        bid = max(bid, DAILY_SALARY * 0.82)

    reserve = DAILY_SALARY * 2
    if budget < reserve:
        bid = min(bid, budget * 0.7)

    if hp >= 4 and no_water == 0 and supply >= 24:
        bid = min(bid, DAILY_SALARY * 0.12)

    bid = max(0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid minimally to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine if I am under high pressure (low HP or missed water)
    # My max HP is 3. So HP <= 2 means I've lost at least 1 HP.
    # no_water_days > 0 means I failed to get water yesterday.
    is_under_pressure = (my_status['hp'] <= 2) or (my_status['no_water_days'] > 0)

    # Calculate current supply situation
    available_water_units = int(day_context['supply'] // WATER_REQ)
    num_players_needing_water = len(alive_opponents) + 1 # Me + opponents
    is_supply_tight = available_water_units < num_players_needing_water

    # React to yesterday's highest bid
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # Scenario 1: Opponents bid very high yesterday (high competition)
        if highest_prev_bid >= DAILY_SALARY * 0.85: 
            if is_under_pressure:
                # I'm under pressure, so bid very aggressively to secure water
                return min(my_status['budget'], highest_prev_bid + 5.0) # Try to outbid
            elif my_status['hp'] >= 3: # My HP is full, but competition is high
                if is_supply_tight: # If supply is also tight, stay competitive
                    return min(my_status['budget'], highest_prev_bid + 1.0)
                else: # Supply is not tight, try to save a bit but still be careful
                    return min(my_status['budget'], DAILY_SALARY * 0.65) # A strong moderate bid

        # Scenario 2: Opponents bid moderately or low yesterday
        else: # highest_prev_bid < DAILY_SALARY * 0.85
            if is_under_pressure:
                # I'm under pressure, so bid high enough to secure water
                # Use a floor of DAILY_SALARY * 0.7 to ensure it's not too low
                return min(my_status['budget'], max(DAILY_SALARY * 0.7, highest_prev_bid + 2.0))
            elif my_status['hp'] >= 3: # My HP is full, and competition was not extreme
                if is_supply_tight: # Supply is tight, bid reasonably to secure
                    return min(my_status['budget'], max(DAILY_SALARY * 0.55, highest_prev_bid + 1.5))
                else: # Supply is abundant, try to save
                    return min(my_status['budget'], max(DAILY_SALARY * 0.4, highest_prev_bid + 0.5))

    # If no yesterday bids (e.g., Day 1, or all opponents failed to bid)
    else:
        if is_under_pressure:
            # If I'm under pressure, bid high to secure water
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        elif my_status['hp'] >= 3: # My HP is full, no prior bids to react to
            if is_supply_tight:
                return min(my_status['budget'], DAILY_SALARY * 0.6) # Moderate bid for tight supply
            else:
                return min(my_status['budget'], DAILY_SALARY * 0.5) # Standard moderate bid

    # Final fallback (should ideally not be reached, but good for safety)
    return min(my_status['budget'], DAILY_SALARY * 0.5)
